  const _ae = addEcr; addEcr = function (e, save) { try { if (e && !e.auteur) { e.auteur = ecrMe(); e.creeLe = new Date().toISOString(); } } catch (x) { } return _ae.apply(this, arguments); };
  const tip = e => "Saisie par " + (e.auteur || "?") + (e.creeLe ? " le " + new Date(e.creeLe).toLocaleString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }).replace(" ", " à ") : "") + (e.modifPar && e.modifPar !== e.auteur ? " · modifiée par " + e.modifPar + (e.modifLe ? " le " + new Date(e.modifLe).toLocaleString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }).replace(" ", " à ") : "") : "");
