    main.querySelectorAll("tr.gr-first[data-e]").forEach(tr => { const e = E.find(x => x.id === tr.dataset.e); if (!e || !e.auteur || tr.querySelector(".ecr-aut")) return; const td = tr.lastElementChild; if (td) td.insertAdjacentHTML("beforeend", ` <span class="ecr-aut" title="${esc(tip(e))}">${esc(ini(e.auteur))}</span>`); });
